tiles.exec:
sensors 2>/dev/null | awk '
function add(s) { printf "%s%s", (n++ ? "," : ""), s }
BEGIN { printf "[" }
/^(Package id 0|Tctl|Tdie|CPU Temperature|CPU|temp1):/ && !cpu {
  if (match($0, /[+-][0-9]+(\.[0-9]+)?/)) { cpu = 1
    add(sprintf("{\"id\":\"cpu_temp\",\"name\":\"CPU temp\",\"type\":\"gauge\",\"value\":%s,\"unit\":\"celsius\",\"max\":100,\"warn\":80,\"bad\":95,\"icon\":\"thermometer\",\"history\":true}", substr($0, RSTART + 1, RLENGTH - 1))) }
}
/^fan[0-9]+:/ && $2 ~ /^[0-9]+$/ && $2 > 0 {
  f = $1; sub(/:/, "", f)
  add(sprintf("{\"id\":\"%s\",\"name\":\"Fan %s\",\"type\":\"number\",\"value\":%s,\"unit\":\"rpm\",\"icon\":\"fan\"}", f, substr(f, 4), $2))
}
END { print "]" }'
